# Completa la línea marcada y compruébala con py check.
def signo(g):
    return 1 if g > 0 else (-1 if g < 0 else 0)

def fgsm(x, gradiente, epsilon):
    nuevo = []
    for xi, gi in zip(x, gradiente):
        v = xi   # ← cambia esta línea: xi + epsilon · signo(gi)
        nuevo.append(min(1.0, max(0.0, v)))
    return nuevo

print(fgsm([0.5, 0.95, 0.0], [2.0, 1.0, -3.0], 0.1))   # [0.6, 1.0, 0.0]
